class Solution {static class E{int v,rev,cap;long cost;E(int a,int b,int c,long d){v=a;rev=b;cap=c;cost=d;}}public long solve(int n,int[][]edges,int required){ArrayList<ArrayList<E>>a=new ArrayList<>();for(int i=0;i<n;i++)a.add(new ArrayList<>());for(int[]e:edges){E f=new E(e[1],a.get(e[1]).size(),e[2],e[3]),b=new E(e[0],a.get(e[0]).size(),0,-(long)e[3]);a.get(e[0]).add(f);a.get(e[1]).add(b);}int sent=0;long total=0,inf=Long.MAX_VALUE/4;while(sent<required){long[]d=new long[n];Arrays.fill(d,inf);int[]from=new int[n],index=new int[n];Arrays.fill(from,-1);d[0]=0;for(int pass=0;pass<n-1;pass++){boolean change=false;for(int u=0;u<n;u++)if(d[u]!=inf)for(int id=0;id<a.get(u).size();id++){E e=a.get(u).get(id);if(e.cap>0&&d[u]+e.cost<d[e.v]){d[e.v]=d[u]+e.cost;from[e.v]=u;index[e.v]=id;change=true;}}if(!change)break;}if(d[n-1]==inf)return -1;int amount=required-sent;for(int v=n-1;v!=0;v=from[v])amount=Math.min(amount,a.get(from[v]).get(index[v]).cap);for(int v=n-1;v!=0;v=from[v]){E e=a.get(from[v]).get(index[v]);e.cap-=amount;a.get(v).get(e.rev).cap+=amount;}sent+=amount;total+=amount*d[n-1];}return total;}}